package com.nicole.stillin;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import org.json.*;
public final class State {
 static final String PREF="still-in-private-v1", COUNTDOWN="countdowns", ALERTS="removal-alarms-v1";
 static final long MINUTE=60000L,HOUR=3600000L;
 static String empty(){return "{\"version\":1,\"active\":[],\"history\":[],\"days\":{},\"settings\":{\"cheeky\":true,\"hours\":{}}}";}
 static synchronized String raw(Context c){return c.getSharedPreferences(PREF,0).getString("state",empty());}
 static JSONObject read(Context c){try{return new JSONObject(raw(c));}catch(Exception e){throw new IllegalStateException("Saved data could not be read",e);}}
 static boolean known(String type){return "tampon cup disc pad liner pants".contains(type)&&!type.isEmpty()&&type.indexOf(' ')<0&&("tampon".equals(type)||"cup".equals(type)||"disc".equals(type)||"pad".equals(type)||"liner".equals(type)||"pants".equals(type));}
 static boolean internal(String t){return "tampon".equals(t)||"cup".equals(t)||"disc".equals(t);}
 static String name(String type){if("pants".equals(type))return "Period pants";return type.substring(0,1).toUpperCase()+type.substring(1);}
 static synchronized String save(Context c,String json){try{if(json.length()>6000000)return "Too many logs to save. Export your records first.";JSONObject next=new JSONObject(json);if(next.optInt("version")!=1||next.optJSONArray("active")==null||next.optJSONArray("history")==null||next.optJSONObject("days")==null||next.optJSONObject("settings")==null)return "Invalid log data";JSONArray sessions=next.getJSONArray("active");if(sessions.length()>6)return "Too many active products";int inside=0;java.util.HashSet<String> seen=new java.util.HashSet<>(),ids=new java.util.HashSet<>();for(int i=0;i<sessions.length();i++){JSONObject x=sessions.getJSONObject(i);String t=x.getString("type"),id=x.getString("id");if(!known(t)||!seen.add(t)||!ids.add(id))return "Invalid product";if(internal(t))inside++;double hours=x.getDouble("hours");if(!Double.isFinite(hours)||hours<.25||hours>("tampon".equals(t)?8:12))return "Invalid wear time";long start=x.getLong("start");if(start>System.currentTimeMillis()+60000)return "Start time is in the future";x.put("due",start+(long)(hours*HOUR));}if(inside>1)return "Only one internal product can be active";JSONObject previous=read(c);if(!c.getSharedPreferences(PREF,0).edit().putString("state",next.toString()).commit())return "Could not save. Try again.";cancelOld(c,previous.optJSONArray("active"));schedule(c);return "ok";}catch(Exception e){return "Could not save: "+e.getMessage();}}
 static void channels(Context c){NotificationManager n=c.getSystemService(NotificationManager.class);NotificationChannel quiet=new NotificationChannel(COUNTDOWN,"Product countdowns",NotificationManager.IMPORTANCE_LOW);quiet.setDescription("Ongoing time remaining for products you log");quiet.setSound(null,null);n.createNotificationChannel(quiet);NotificationChannel alerts=new NotificationChannel(ALERTS,"Time to change",NotificationManager.IMPORTANCE_HIGH);alerts.setDescription("Removal reminders and overdue alerts");alerts.enableVibration(true);android.media.AudioAttributes attrs=new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_ALARM).build();alerts.setSound(Settings.System.DEFAULT_ALARM_ALERT_URI,attrs);n.createNotificationChannel(alerts);}
 static int nid(String id){return 1000+(id.hashCode()&0x1fffffff);}
 static PendingIntent open(Context c){return PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static Notification countdown(Context c,JSONObject x)throws Exception{long due=x.getLong("due");boolean late=due<=System.currentTimeMillis();String label=name(x.getString("type"));Notification pub=new Notification.Builder(c,COUNTDOWN).setSmallIcon(R.drawable.ic_notification).setContentTitle("Still In? · Product timer").setContentText(late?"A product is due for a change":"A product reminder is running").setWhen(due).setUsesChronometer(true).setChronometerCountDown(!late).build();return new Notification.Builder(c,COUNTDOWN).setSmallIcon(R.drawable.ic_notification).setColor(0xff7545df).setContentTitle(label+(late?" · overdue":" · time remaining")).setContentText(late?"Time to remove or change. Tap to log it.":"Tap to log removal or a change.").setWhen(due).setShowWhen(true).setUsesChronometer(true).setChronometerCountDown(!late).setOngoing(true).setOnlyAlertOnce(true).setContentIntent(open(c)).setVisibility(Notification.VISIBILITY_PRIVATE).setPublicVersion(pub).setCategory(Notification.CATEGORY_REMINDER).build();}
 static PendingIntent alarm(Context c){return PendingIntent.getBroadcast(c,1,new Intent(c,ReminderReceiver.class).setAction("com.nicole.stillin.DUE"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static boolean exact(Context c){return Build.VERSION.SDK_INT<31||c.getSystemService(AlarmManager.class).canScheduleExactAlarms();}
 static void setAlarm(Context c,long when,PendingIntent p){AlarmManager a=c.getSystemService(AlarmManager.class);try{if(exact(c))a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);}catch(SecurityException e){a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);}}
 static void cancelOld(Context c,JSONArray old){if(old==null)return;NotificationManager n=c.getSystemService(NotificationManager.class);for(int i=0;i<old.length();i++){JSONObject x=old.optJSONObject(i);if(x!=null){n.cancel(nid(x.optString("id")));n.cancel(nid(x.optString("id"))+1);}}}
 static synchronized void schedule(Context c){try{channels(c);JSONObject s=read(c);JSONArray active=s.getJSONArray("active");AlarmManager a=c.getSystemService(AlarmManager.class);a.cancel(alarm(c));long now=System.currentTimeMillis(),next=Long.MAX_VALUE;NotificationManager n=c.getSystemService(NotificationManager.class);for(int i=0;i<active.length();i++){JSONObject x=active.getJSONObject(i);long due=x.getLong("due"),early=due-30*MINUTE;if(n.areNotificationsEnabled())n.notify(nid(x.getString("id")),countdown(c,x));next=Math.min(next,Schedule.next(now,due));}if(next!=Long.MAX_VALUE)setAlarm(c,Math.max(now+1000,next),alarm(c));}catch(Exception e){android.util.Log.e("StillIn","Reminder scheduling failed",e);}}
 static synchronized void fire(Context c){try{JSONObject s=read(c);JSONArray active=s.getJSONArray("active");long now=System.currentTimeMillis();for(int i=0;i<active.length();i++){JSONObject x=active.getJSONObject(i);long due=x.getLong("due");if(now<due-30*MINUTE)continue;String id=x.getString("id");boolean late=now>=due;long last=c.getSharedPreferences(PREF,0).getLong("alert-"+id,0);if(last>0&&((!late&&last<due)||(late&&last>=due&&now-last<14*MINUTE)))continue;String title=late?name(x.getString("type"))+" is due out":"30 minutes until a change";String text=late?"Remove or change it now. Tap to log it.":name(x.getString("type"))+" · your reminder time is coming up.";Notification notification=new Notification.Builder(c,ALERTS).setSmallIcon(R.drawable.ic_notification).setColor(0xffcf3c61).setContentTitle(title).setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setCategory(Notification.CATEGORY_ALARM).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(open(c)).setAutoCancel(true).build();c.getSystemService(NotificationManager.class).notify(nid(id)+1,notification);c.getSharedPreferences(PREF,0).edit().putLong("alert-"+id,now).apply();}schedule(c);}catch(Exception e){android.util.Log.e("StillIn","Reminder failed",e);}}
 static void test(Context c){channels(c);PendingIntent p=PendingIntent.getBroadcast(c,99,new Intent(c,ReminderReceiver.class).setAction("com.nicole.stillin.TEST"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);setAlarm(c,System.currentTimeMillis()+10000,p);}
}
